CREATE    VIEW [FO].[vwSalesTable]
AS
SELECT
	T1.[SALESID],
	T1.[CUSTACCOUNT],
	T1.[INVOICEACCOUNT],
	T1.[SALESNAME],
	T1.[CASHDISCBASEDATE],
	T1.[CASHDISCBASEDAYS],
	T1.[CASHDISCPERCENT],
	T1.[CURRENCYCODE],
	T1.[CUSTGROUP],
	CASE
		WHEN T1.[CUSTGROUP] = 10 THEN 'Members'
		WHEN T1.[CUSTGROUP] = 20 THEN 'Non-Members'
		WHEN T1.[CUSTGROUP] = 30 THEN 'Firms'
		WHEN T1.[CUSTGROUP] = 40 THEN 'Intercompany'
	END AS [CUSTGROUP_DESCRIPTION],
	T1.[CUSTOMERREF],
	T1.[CUSTINVOICEID],
	T1.[DEADLINE],
	T1.[DELIVERYDATE],
	T1.[DOCUMENTSTATUS],
	T1.[EMAIL],
	T1.[ESTIMATE],
	T1.[FIXEDDUEDATE],
	T1.[INCLTAX],
	T1.[PAYMENTSCHED],
	T1.[PAYMMODE],
	T1.[PAYMSPEC],
	T1.[POSTINGPROFILE],
	T1.[PURCHID],
	T1.[PURCHORDERFORMNUM],
	T1.[RECEIPTDATECONFIRMED],
	T1.[RECEIPTDATEREQUESTED],
	T1.[RELEASESTATUS],
	T1.[RETURNDEADLINE],
	T1.[SALESSTATUS],
	CASE
		WHEN T1.[SALESSTATUS] = 1 THEN 'Open Order'
		WHEN T1.[SALESSTATUS] = 2 THEN 'Delivered'
		WHEN T1.[SALESSTATUS] = 3 THEN 'Invoiced'
		WHEN T1.[SALESSTATUS] = 4 THEN 'Cancelled'
	END AS [SHIPPINGDATECONFIRMED],
	T1.[SHIPPINGDATEREQUESTED],
	T1.[SMMCAMPAIGNID],
	T1.[SMMSALESAMOUNTTOTAL],
	T1.[TAXGROUP],
	T2.[DISPLAYVALUE] AS [DEFAULTDIMENSIONDISPLAYVALUE],
	T1.[DATAAREAID]
FROM [synapse_fo].[SALESTABLE] T1
	LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T2 ON (
			(T1.DEFAULTDIMENSION = T2.RECID)
			AND (T1.PARTITION = T2.PARTITION)
			)
